"use client";
/* Balloon, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Balloon(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("balloon"); }, []);
  return React.createElement("piix-pal", { "pal": "balloon", ...piixAttrs(props) });
}

export default Balloon;
